def process_line(raw):
    try:
        value = json.loads(raw, parse_constant=_bad_const)
    except Exception:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    rid = None
    if isinstance(value, dict):
        cand = value.get('id')
        if is_name(cand):
            rid = cand
    try:
        inst = parse_request(value)
    except Invalid:
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    except RecursionError:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    except Exception:
        traceback.print_exc()
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    try:
        return solve(inst)
    except Exception:
        traceback.print_exc()
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}


def main():
    data = sys.stdin.buffer.read()
    if not data:
        return
    lines = data.split(b'\n')
    if lines and lines[-1] == b'':
        lines.pop()
    out = sys.stdout
    for raw in lines:
        out.write(json.dumps(process_line(raw), separators=(',', ':')))
        out.write('\n')
        out.flush()


if __name__ == '__main__':
    main()
